// ELF 0x213230 (C2) / 0x213570 (C1); vtable GOT -0x1158. BotBehaviour(null modifiers, null
// curve, getMaxNBots); +0x24 = checkPointer(new float[n]), then the +0x08 targets =
// checkPointer(new unsigned int[n]) (operator new 0x28), no pattern (+0x0C = 0); every bot
// starts with urgency and +0x24 at 0.0f and target -1.
BBFireUnarmed::BBFireUnarmed(unsigned char index, unsigned char queue)
    : BotBehaviour(0, 0, static_cast<IAISettings*>(CommonSingletonServer::m_iaiSettings)->getMaxNBots())
{
    m_index = index;
    m_queue = queue;
    const int bots = static_cast<IAISettings*>(CommonSingletonServer::m_iaiSettings)->getMaxNBots();
    m_value24 = checkPointer(new float[bots]);
    m_targets = checkPointer(new unsigned int[bots]);
    m_pattern = 0;
    for (int i = 0; i < bots; ++i)
    {
        m_urgency[i] = 0.0f;
        m_value24[i] = 0.0f;
        m_targets[i] = static_cast<unsigned int>(-1);
    }
}

// ELF 0x2138B0 (D2) / 0x213910 (D1) / 0x213970 (D0): delete[] +0x08, then +0x24 (each when set),
// then ~BotBehaviour.
BBFireUnarmed::~BBFireUnarmed()
{
    if (m_targets)
        delete[] m_targets;
    if (m_value24)
        delete[] m_value24;
}

// ELF 0x2139E0 (Ghidra; listing for the constants and the return). Always returns 0.0; the
// urgency goes to +0x24 and to the bot's fire inclination (+0x188).
// Without `evaluate`: a target that no longer resolves marks the change and clears +0x24;
// otherwise the stored +0x24 is fed to the fire inclination again.
// With it: every sided sensed object of another side with a physical part, alive, not of the
// three excluded type bits (0x20000 / 0x100000 / 0x800000) and within 250 (distance floored at
// 0.5) of the equipment's position is weighed when it has a unit and its vehicle is occupied
// for this side: over it and its secondary objects, (battle strength against the own strength
// type + the information's strength) * armour class of its strength type * the order factor
// (the memory's +0x08 while the object is in the bot's order list, counted at most once per order)
// * the area factor (0.75 outside the ordered area, again 0.75 when a mobile bot's target is
// outside it), then * time factor (1 / (age * 0.05 + 1) for indirect senses) / max(0.1,
// distance * 1.5 * 0.2), and * 0.33 when the summed strength is at most the harmless threshold.
// The best becomes the target, unless the current target scored and stays within 1.2 of it.
// A two-entry ignore list (the equipment's AI object, null) is built and never used, and the
// normalised direction is computed and dropped, as compiled.
float BBFireUnarmed::calculateUrgency(Bot* bot, bool evaluate, float modifier)
{
    if (!evaluate)
    {
        Information* const target = informationManager->getInformation(m_targets[bot->getBotId()]);
        if (!target)
        {
            m_targetChanged[bot->getBotId()] = true;
            m_value24[bot->getBotId()] = 0.0f;
            return 0.0f;
        }
        m_targetChanged[bot->getBotId()] = false;
        bot->addToFireInclination(m_value24[bot->getBotId()]);
        return 0.0f;
    }

    const float* const armourClass =
        static_cast<IAISettings*>(CommonSingletonServer::m_iaiSettings)->getArmourClassValues();   // +0x94
    Information* const equipment = informationManager->getInformation(bot->getCurrentEquipment());
    IPIMobile* const ownMobile = equipment->getMobile();
    const int ownStrengthType = equipment->getPhysical()->getStrengthType();
    const Vec3 position = equipment->getPosition();
    float currentTargetScore = 0.0f;
    unsigned int countedOrders = 0;
    const int side = bot->getSide();
    const unsigned int currentTarget = m_targets[bot->getBotId()];
    bool currentTargetScored = false;
    std::vector<IAIObject*> ignore;
    ignore.push_back(equipment->getAIObject());
    ignore.push_back(0);

    const unsigned int botId = bot->getBotId();
    const int orderedArea = IAIMain::m_instance->getSAI(side)->getBotOrderedPos(botId);
    AIStrategicArea* const area =
        static_cast<AIStrategicArea*>(AIStrategicObjectManager::getInstance()->getStrategicObject(orderedArea));
    float areaFactor;
    if (!area)
        areaFactor = 1.0f;
    else
        areaFactor = area->isInside(position) ? 1.0f : 0.75f;

    const double now = static_cast<IBFTimer*>(CommonSingletonServer::m_iBFTimer)->getGameTime();
    float bestScore = currentTargetScore;
    const std::map<unsigned int, SensedObject*>& sensed = bot->getSensedObjects();
    for (std::map<unsigned int, SensedObject*>::const_iterator it = sensed.begin(); it != sensed.end(); ++it)
    {
        SensedObject* const object = it->second;
        if (!(object->m_flags & SensedObject::SENSE_SIDED))
            continue;
        Information* const info = informationManager->getInformation(object->m_handle);
        if (!info || info->getSide() == side || !info->getPhysical())
            continue;
        const unsigned int typeFlags = info->getObjectTypeFlags();
        if ((typeFlags & 0x20000) || (typeFlags & 0x100000) || (typeFlags & 0x800000))
            continue;
        if (!(info->getPhysical()->getHealth() > 0.0f))
            continue;

        Vec3 targetPosition;
        targetPosition.x = 0.0f;
        targetPosition.y = 0.0f;
        targetPosition.z = 0.0f;
        if (info->getMobile())
            info->getMobile()->getPositionEstimate(targetPosition);
        else
            targetPosition = info->getPosition();
        Vec3 direction;
        direction.x = targetPosition.x - position.x;
        direction.y = targetPosition.y - position.y;
        direction.z = targetPosition.z - position.z;
        float distance = std::sqrt(direction.z * direction.z + direction.x * direction.x
                                   + direction.y * direction.y);
        if (!(0.5f <= distance))
            distance = 0.5f;
        if (distance > 250.0f)
            continue;

        float timeFactor = 1.0f;
        const float inverse = 1.0f / distance;
        direction.x = direction.x * inverse;
        direction.y = direction.y * inverse;
        direction.z = inverse * direction.z;
        (void)direction;
        if (object->m_flags & SensedObject::SENSE_INDIRECT)
        {
            const float age = static_cast<float>(now - object->m_firstSeenTime);
            timeFactor = 1.0f / (age * 0.05f + 1.0f);
        }

        if (bot->isOrderedBehaviour(m_index) && bot->isTakingOrders()
            && bot->getOrderList(m_index)->size() > countedOrders)
        {
            if (bot->getOrderList(m_index)->end()
                != std::find(bot->getOrderList(m_index)->begin(), bot->getOrderList(m_index)->end(),
                             object->m_handle))
                ++countedOrders;
        }

        float targetAreaFactor = areaFactor;
        if (ownMobile && area && !area->isInside(targetPosition))
            targetAreaFactor = areaFactor * 0.75f;

        if (!info->getUnit() || !vehicleOccupied(object->m_handle, side))
            continue;

        float strengthSum = 0.0f;
        const unsigned int handle = object->m_handle;
        int secondary = info->getFirstSecondaryObjectIterator();
        const int targetStrengthType = info->getPhysical()->getStrengthType();
        Information* part = info;
        float score = strengthSum;
        do
        {
            IPIUnit* const unit = part->getUnit();
            strengthSum = strengthSum + unit->getBattleStrengths()[ownStrengthType];
            bool ordered = false;
            if (bot->isOrderedBehaviour(m_index) && bot->isTakingOrders()
                && bot->getOrderList(m_index)->size() > countedOrders)
            {
                if (bot->getOrderList(m_index)->end()
                    != std::find(bot->getOrderList(m_index)->begin(), bot->getOrderList(m_index)->end(),
                                 handle))
                    ordered = true;
            }
            float orderFactor;
            if (ordered)
            {
                ++countedOrders;
                orderFactor = bot->getMemory()->m_float8;
            }
            else
            {
                orderFactor = 1.0f;
            }
            score = (unit->getBattleStrengths()[ownStrengthType] + part->getStrength())
                        * armourClass[targetStrengthType] * orderFactor * targetAreaFactor
                    + score;
            part = informationManager->getInformation(info->getSecondaryObject(secondary, side));
        }
        while (part);

        float distanceFactor = distance * 1.5f * 0.2f;
        if (distanceFactor <= 0.1f)
            distanceFactor = 0.1f;
        score = score * (timeFactor / distanceFactor);
        if (strengthSum <= static_cast<float>(static_cast<BotMain*>(bot)->getHarmlessThrsh()))
            score = score * 0.33f;
        if (info->getUnit())
        {
            if (currentTarget == object->m_handle)
            {
                currentTargetScore = score;
                currentTargetScored = true;
            }
            if (bestScore < score)
            {
                bestScore = score;
                m_targets[bot->getBotId()] = object->m_handle;
            }
        }
    }

    if (bestScore <= 0.0f)
    {
        m_targetChanged[bot->getBotId()] = !currentTargetScored;
        m_value24[bot->getBotId()] = 0.0f;
        m_value24[bot->getBotId()] += getIncomingFireUrgency(static_cast<BotMain*>(bot));
        bot->addToFireInclination(m_value24[bot->getBotId()]);
        return 0.0f;
    }

    if (!currentTargetScored || currentTargetScore * 1.2f <= bestScore)
    {
        bot->getBotId();                                              // called, result unused
        currentTargetScored = false;
    }
    else
    {
        m_targets[bot->getBotId()] = currentTarget;
    }
    if (bot->isOrderedBehaviour(m_index) && bot->isTakingOrders() && bot->getOrderList(m_index)->empty())
        bestScore = bestScore * bot->getMemory()->m_float8;
    m_targetChanged[bot->getBotId()] = !currentTargetScored;
    m_value24[bot->getBotId()] = DecleiningSlopeCurve::calculate(bestScore + bestScore) * (modifier * 1.0f);
    m_value24[bot->getBotId()] += getIncomingFireUrgency(static_cast<BotMain*>(bot));
    bot->addToFireInclination(m_value24[bot->getBotId()]);
    return 0.0f;
}

// ELF 0x214800 (Ghidra). Ten times the strongest incoming fire against the equipment's strength
// type, over a copy of the bot's incoming-fire list (the type asked for once per entry).
float BBFireUnarmed::getIncomingFireUrgency(BotMain* bot)
{
    float strongest = 0.0f;
    const std::list<std::pair<FireObject*, unsigned int> > incoming = *bot->getIncommingFire();   // +0xA0
    Information* const equipment = informationManager->getInformation(bot->getCurrentEquipment());
    IPIPhysical* const physical = equipment->getPhysical();
    for (std::list<std::pair<FireObject*, unsigned int> >::const_iterator it = incoming.begin();
         it != incoming.end(); ++it)
    {
        const float strength = it->first->getBattleStrength(physical->getStrengthType());
        strongest = (strength <= strongest) ? strongest : strength;
    }
    return strongest * 10.0f;
}

